sp_widget.client_script:
function(spUtil, $window, $timeout, $scope) {
  var c = this;

  // ── User session ──────────────────────────────────────────
  c.sessionUser = {
    name:     ($scope.user && $scope.user.name)   || c.data.currentUser.name   || 'Reviewer',
    email:    c.data.currentUser.email            || '',
    sys_id:   ($scope.user && $scope.user.sys_id) || c.data.currentUser.sys_id || '',
    initials: ($window.NOW && $window.NOW.user_initials) || c.data.currentUser.initials || 'R',
    loggedIn: $scope.user && $scope.user.logged_in
  };

  // ── Navigation ────────────────────────────────────────────
  c.activeSection = 'home';
  c.sidebarOpen   = true;

  c.navTo = function(section) {
    c.activeSection = section;
    if (section === 'proposals') c.proposalPage = 1;
  };
  c.toggleSidebar = function() { c.sidebarOpen = !c.sidebarOpen; };

  c.profileOpen = false;
  c.toggleProfile = function($event) { $event.stopPropagation(); c.profileOpen = !c.profileOpen; };
  c.logout    = function() { $window.location.href = c.data.logoutUrl || '/login.do?logout=true'; };
  c.goToProfile = function() { c.profileOpen = false; $window.location.href = c.data.profilePage || '?id=user_profile'; };

  // ── Filters ───────────────────────────────────────────────
  c.searchText     = '';
  c.statusFilter   = '';
  c.categoryFilter = '';
  c.programFilter  = '';

  // ── Pagination ────────────────────────────────────────────
  c.proposalPage = 1;
  c.pageSize     = 12;

  $scope.$watchGroup(
    ['c.searchText','c.statusFilter','c.categoryFilter','c.programFilter'],
    function() { c.proposalPage = 1; }
  );

  // ── Dropdown options ──────────────────────────────────────
  c.categoryOptions = function() {
    var seen = {}, opts = [];
    (c.data.reviews || []).forEach(function(r) {
      if (r.status !== 'Review completed' && r.program_category && !seen[r.program_category]) {
        seen[r.program_category] = true; opts.push(r.program_category);
      }
    });
    return opts.sort();
  };

  c.programOptions = function() {
    var seen = {}, opts = [];
    (c.data.reviews || []).forEach(function(r) {
      if (r.status !== 'Review completed' && r.program && !seen[r.program]) {
        seen[r.program] = true; opts.push(r.program);
      }
    });
    return opts.sort();
  };

  // ── Status options (all 5 real values) ────────────────────
  c.allStatuses = [
    'Review pending',
    'Review in progress',
    'Review completed',
    'Escalated',
    'Declined by Reviewer'
  ];

  // ── Filter logic ──────────────────────────────────────────
  c.filteredProposals = function() {
    return (c.data.reviews || []).filter(function(r) {
      if (r.status === 'Review completed') return false;
      if (c.statusFilter   && r.status           !== c.statusFilter)   return false;
      if (c.categoryFilter && r.program_category !== c.categoryFilter) return false;
      if (c.programFilter  && r.program          !== c.programFilter)  return false;
      if (c.searchText) {
        var txt = c.searchText.toLowerCase();
        if ((r.number           || '').toLowerCase().indexOf(txt) === -1 &&
            (r.program          || '').toLowerCase().indexOf(txt) === -1 &&
            (r.applicant        || '').toLowerCase().indexOf(txt) === -1 &&
            (r.program_category || '').toLowerCase().indexOf(txt) === -1) return false;
      }
      return true;
    });
  };

  c.pagedProposals = function() {
    var all = c.filteredProposals();
    var start = (c.proposalPage - 1) * c.pageSize;
    return all.slice(start, start + c.pageSize);
  };

  c.totalPages = function() { return Math.ceil(c.filteredProposals().length / c.pageSize) || 1; };

  c.pageNumbers = function() {
    var total = c.totalPages(), current = c.proposalPage, pages = [];
    var start = Math.max(1, current - 2), end = Math.min(total, current + 2);
    if (start > 1) pages.push(1);
    if (start > 2) pages.push('...');
    for (var i = start; i <= end; i++) pages.push(i);
    if (end < total - 1) pages.push('...');
    if (end < total) pages.push(total);
    return pages;
  };

  c.goToPage = function(p) { if (p !== '...' && p >= 1 && p <= c.totalPages()) c.proposalPage = p; };
  c.prevPage = function() { if (c.proposalPage > 1) c.proposalPage--; };
  c.nextPage = function() { if (c.proposalPage < c.totalPages()) c.proposalPage++; };

  // ── Completed / Recent ────────────────────────────────────
  c.completedReviews = function() {
    return (c.data.reviews || []).filter(function(r) { return r.status === 'Review completed'; });
  };

  c.recentActivity = function() {
    return (c.data.reviews || []).filter(function(r) { return r.status !== 'Review completed'; }).slice(0, 8);
  };

  c.overdueReviews = function() {
    return (c.data.reviews || []).filter(function(r) { return r.is_overdue; });
  };

  c.dueSoonReviews = function() {
    return (c.data.reviews || []).filter(function(r) { return r.is_due_soon; });
  };

  c.openRecord = function(rev) {
    if (!rev || !rev.sys_id) return;
    $window.location.href = '/review?id=review_proposal_detail_page&sys_id=' + rev.sys_id;
  };

  c.scoreWidth = function(score) {
    if (!score) return '0%';
    return Math.min(Math.round((parseInt(score) / 10) * 100), 100) + '%';
  };

  // deadline CSS helper
  c.deadlineClass = function(rev) {
    if (rev.is_overdue)  return 'rvd-deadline--overdue';
    if (rev.is_due_soon) return 'rvd-deadline--soon';
    return 'rvd-deadline--ok';
  };

  // status color helper
  c.statusChipClass = function(status) {
    if (status === 'Review completed')      return 'rvd-chip--green';
    if (status === 'Escalated')             return 'rvd-chip--red';
    if (status === 'Declined by Reviewer')  return 'rvd-chip--rose';
    if (status === 'Review pending')        return 'rvd-chip--slate';
    return 'rvd-chip--amber'; // in progress
  };

  // ── Animated KPI counters ─────────────────────────────────
  c.animatedStats = { total:0, inProgress:0, completed:0, escalated:0, declined:0, pending:0 };

  function animateCount(key, target) {
    if (!target) return;
    var step = Math.ceil(target / 30), current = 0;
    var interval = setInterval(function() {
      current += step;
      if (current >= target) { current = target; clearInterval(interval); }
      c.animatedStats[key] = current;
      $timeout(function() {}, 0);
    }, 30);
  }

  $timeout(function() {
    var s = c.data.stats || {};
    animateCount('total',      s.total      || 0);
    animateCount('inProgress', s.inProgress || 0);
    animateCount('completed',  s.completed  || 0);
    animateCount('escalated',  s.escalated  || 0);
    animateCount('declined',   s.declined   || 0);
    animateCount('pending',    s.pending    || 0);
  }, 300);

  // ════════════════════════════════════════════════════════
  // CHART.JS CHARTS
  // ════════════════════════════════════════════════════════
  c.drawCharts = function() {
    var s       = c.data.stats  || {};
    var reviews = c.data.reviews || [];
    var total   = s.total      || 0;
    var prog    = s.inProgress || 0;
    var done    = s.completed  || 0;
    var esc     = s.escalated  || 0;
    var dec     = s.declined   || 0;
    var pend    = s.pending    || 0;

    if (typeof Chart === 'undefined') return;
    Chart.defaults.font.family = "'Inter','Segoe UI',sans-serif";
    Chart.defaults.color       = '#64748b';

    // helper: destroy & recreate
    function makeChart(id, config) {
      var el = document.getElementById(id);
      if (!el) return;
      if (el._ci) { try { el._ci.destroy(); } catch(e){} }
      el._ci = new Chart(el, config);
    }

    /* ── 1. Full-status Donut ── */
    makeChart('rvdDonutChart', {
      type: 'doughnut',
      data: {
        labels: ['In Progress','Completed','Escalated','Declined','Pending'],
        datasets: [{
          data: [prog, done, esc, dec, pend],
          backgroundColor: ['#6366f1','#10b981','#ef4444','#f97316','#94a3b8'],
          borderWidth: 5, borderColor: '#fff', hoverOffset: 10
        }]
      },
      options: {
        cutout: '74%',
        plugins: {
          legend: { display: false },
          tooltip: { callbacks: { label: function(ctx) {
            var pct = total ? Math.round(ctx.parsed / total * 100) : 0;
            return ' ' + ctx.label + ': ' + ctx.parsed + ' (' + pct + '%)';
          }}}
        },
        animation: { animateRotate: true, duration: 1400, easing: 'easeOutQuart' }
      }
    });

    /* ── 2. Horizontal Status Bar ── */
    makeChart('rvdProgressBar', {
      type: 'bar',
      data: {
        labels: ['Pending','In Progress','Escalated','Declined','Completed'],
        datasets: [{
          label: 'Proposals',
          data: [pend, prog, esc, dec, done],
          backgroundColor: ['#94a3b8','#6366f1','#ef4444','#f97316','#10b981'],
          borderRadius: 10, borderSkipped: false
        }]
      },
      options: {
        indexAxis: 'y',
        plugins: { legend: { display: false } },
        scales: {
          x: { max: total || 10, grid: { color: '#f1f5f9' },
               ticks: { color: '#94a3b8', font: { size: 11 } } },
          y: { grid: { display: false },
               ticks: { color: '#374151', font: { size: 12, weight: '700' } } }
        },
        animation: { duration: 1200, easing: 'easeOutCubic' }
      }
    });

    /* ── 3. Deadline Timeline Bar — overdue / due soon / on track ── */
    var overdue  = s.overdue  || 0;
    var dueSoon  = s.dueSoon  || 0;
    var onTrack  = Math.max(0, total - done - dec - overdue - dueSoon);
    makeChart('rvdDeadlineChart', {
      type: 'bar',
      data: {
        labels: ['Overdue','Due in ≤3 Days','On Track'],
        datasets: [{
          label: 'Reviews',
          data: [overdue, dueSoon, onTrack],
          backgroundColor: ['#ef4444','#f59e0b','#10b981'],
          borderRadius: 12, borderSkipped: false, barThickness: 40
        }]
      },
      options: {
        plugins: { legend: { display: false } },
        scales: {
          x: { grid: { display: false }, ticks: { color: '#374151', font: { size: 12, weight: '700' } } },
          y: { beginAtZero: true, grid: { color: '#f1f5f9' },
               ticks: { color: '#94a3b8', font: { size: 11 }, precision: 0 } }
        },
        animation: { duration: 1200, easing: 'easeOutCubic' }
      }
    });

    /* ── 4. Review Activity Line (simulated from review data) ── */
    var days = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
    var dist = [0,0,0,0,0,0,0];
    reviews.forEach(function(r, i) { dist[i % 7]++; });
    makeChart('rvdActivityLine', {
      type: 'line',
      data: {
        labels: days,
        datasets: [{
          label: 'Reviews Actioned',
          data: dist,
          borderColor: '#6366f1',
          backgroundColor: 'rgba(99,102,241,0.08)',
          borderWidth: 3,
          pointBackgroundColor: '#6366f1',
          pointBorderColor: '#fff', pointBorderWidth: 2,
          pointRadius: 6, pointHoverRadius: 9,
          tension: 0.45, fill: true
        }]
      },
      options: {
        plugins: { legend: { display: false } },
        scales: {
          x: { grid: { display: false }, ticks: { color: '#94a3b8', font: { size: 11, weight: '600' } } },
          y: { beginAtZero: true, grid: { color: '#f1f5f9' },
               ticks: { color: '#94a3b8', font: { size: 11 }, stepSize: 1, precision: 0 } }
        },
        animation: { duration: 1600, easing: 'easeOutQuart' }
      }
    });

    /* ── 5. Half-Donut Gauge — Escalation Rate ── */
    var escRate = total ? Math.round(esc / total * 100) : 0;
    makeChart('rvdGauge', {
      type: 'doughnut',
      data: {
        datasets: [{
          data: [escRate, 100 - escRate],
          backgroundColor: [escRate > 10 ? '#ef4444' : '#10b981', '#f1f5f9'],
          borderWidth: 0, circumference: 180, rotation: 270
        }]
      },
      options: {
        cutout: '75%',
        plugins: { legend: { display: false }, tooltip: { enabled: false } },
        animation: { animateRotate: true, duration: 1400 }
      }
    });

    /* ── 6. Category Grouped Bar ── */
    var catMap = {};
    reviews.forEach(function(r) {
      var cat = r.program_category || 'Uncategorized';
      if (!catMap[cat]) catMap[cat] = { prog:0, done:0, esc:0, dec:0, pend:0 };
      if (r.status === 'Review in progress')   catMap[cat].prog++;
      else if (r.status === 'Review completed') catMap[cat].done++;
      else if (r.status === 'Escalated')        catMap[cat].esc++;
      else if (r.status === 'Declined by Reviewer') catMap[cat].dec++;
      else if (r.status === 'Review pending')   catMap[cat].pend++;
    });
    var catLabels = Object.keys(catMap);
    if (catLabels.length) {
      makeChart('rvdCategoryChart', {
        type: 'bar',
        data: {
          labels: catLabels,
          datasets: [
            { label: 'In Progress', data: catLabels.map(function(k){ return catMap[k].prog; }),
              backgroundColor: '#6366f1', borderRadius: 6, borderSkipped: false },
            { label: 'Completed',   data: catLabels.map(function(k){ return catMap[k].done; }),
              backgroundColor: '#10b981', borderRadius: 6, borderSkipped: false },
            { label: 'Escalated',   data: catLabels.map(function(k){ return catMap[k].esc;  }),
              backgroundColor: '#ef4444', borderRadius: 6, borderSkipped: false },
            { label: 'Declined',    data: catLabels.map(function(k){ return catMap[k].dec;  }),
              backgroundColor: '#f97316', borderRadius: 6, borderSkipped: false },
            { label: 'Pending',     data: catLabels.map(function(k){ return catMap[k].pend; }),
              backgroundColor: '#94a3b8', borderRadius: 6, borderSkipped: false }
          ]
        },
        options: {
          plugins: {
            legend: { position: 'bottom', labels: {
              usePointStyle: true, pointStyle: 'circle',
              font: { size: 11, weight: '600' }, color: '#374151', padding: 16
            }}
          },
          scales: {
            x: { grid: { display: false }, ticks: { color: '#94a3b8', font: { size: 11 } } },
            y: { beginAtZero: true, grid: { color: '#f1f5f9' },
                 ticks: { color: '#94a3b8', font: { size: 11 }, precision: 0 } }
          },
          animation: { duration: 1200, easing: 'easeOutCubic' }
        }
      });
    }

    /* ── 7. Reviewer Group Load Bar (who has how many) ── */
    var grpMap = {};
    reviews.forEach(function(r) {
      var grp = r.assignment_group || 'Unassigned';
      grpMap[grp] = (grpMap[grp] || 0) + 1;
    });
    var grpLabels = Object.keys(grpMap);
    if (grpLabels.length) {
      makeChart('rvdGroupChart', {
        type: 'bar',
        data: {
          labels: grpLabels,
          datasets: [{
            label: 'Proposals Assigned',
            data: grpLabels.map(function(k){ return grpMap[k]; }),
            backgroundColor: grpLabels.map(function(_, i) {
              var palette = ['#6366f1','#10b981','#f59e0b','#ef4444','#8b5cf6','#0ea5e9','#f97316'];
              return palette[i % palette.length];
            }),
            borderRadius: 10, borderSkipped: false
          }]
        },
        options: {
          indexAxis: 'y',
          plugins: { legend: { display: false } },
          scales: {
            x: { beginAtZero: true, grid: { color: '#f1f5f9' },
                 ticks: { color: '#94a3b8', font: { size: 11 }, precision: 0 } },
            y: { grid: { display: false },
                 ticks: { color: '#374151', font: { size: 12, weight: '700' } } }
          },
          animation: { duration: 1200, easing: 'easeOutCubic' }
        }
      });
    }
  };

  // ── Load Chart.js then draw ───────────────────────────────
  function loadChartJS(cb) {
    if (typeof Chart !== 'undefined') { cb(); return; }
    var s = document.createElement('script');
    s.src = 'https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js';
    s.onload = cb;
    document.head.appendChild(s);
  }

  $timeout(function() {
    loadChartJS(function() {
      $timeout(function() { c.drawCharts(); }, 100);
    });
  }, 500);

  $scope.$watch('c.activeSection', function(newVal) {
    if (newVal === 'home') {
      $timeout(function() { c.drawCharts(); }, 150);
    }
  });
}

sp_widget.css:
/* ═══════════════════════════════════════════════════
   SHELL & LAYOUT
═══════════════════════════════════════════════════ */
.rvd-shell {
  display: flex;
  min-height: 100vh;
  background: #f0f2f8;
  font-family: 'Inter', 'Segoe UI', sans-serif;
  overflow: hidden;
  margin-top: 4.5%;
}

/* ═══════════════════════════════════════════════════
   SIDEBAR
═══════════════════════════════════════════════════ */
.rvd-sidebar {
  width: 240px;
  min-width: 240px;
  background: linear-gradient(180deg, #1e1b4b 0%, #312e81 60%, #3730a3 100%);
  display: flex;
  flex-direction: column;
  padding: 0;
  transition: width 0.3s cubic-bezier(.4,0,.2,1),
              min-width 0.3s cubic-bezier(.4,0,.2,1);
  overflow: hidden;
  box-shadow: 4px 0 24px rgba(49,46,129,0.18);
  z-index: 100;
}

.rvd-sidebar--collapsed {
  width: 64px;
  min-width: 64px;
}

.rvd-sidebar--collapsed .rvd-brand-text,
.rvd-sidebar--collapsed .rvd-nav__label,
.rvd-sidebar--collapsed .rvd-nav__badge,
.rvd-sidebar--collapsed .rvd-reviewer-info,
.rvd-sidebar--collapsed .rvd-profile-details,
.rvd-sidebar--collapsed .rvd-profile-caret {
  opacity: 0;
  pointer-events: none;
  width: 0;
  overflow: hidden;
}

/* Brand */
.rvd-sidebar__brand {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 24px 20px 20px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}

.rvd-brand-icon {
  width: 36px;
  height: 36px;
  background: rgba(255,255,255,0.15);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 16px;
  flex-shrink: 0;
}

.rvd-brand-text {
  font-size: 16px;
  font-weight: 700;
  color: #fff;
  letter-spacing: 0.3px;
  white-space: nowrap;
  transition: opacity 0.2s, width 0.3s;
}

/* Nav */
.rvd-nav {
  flex: 1;
  padding: 16px 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.rvd-nav__item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 10px;
  color: rgba(255,255,255,0.6);
  cursor: pointer;
  transition: background 0.18s, color 0.18s, transform 0.15s;
  text-decoration: none;
  position: relative;
  white-space: nowrap;
}

.rvd-nav__item:hover {
  background: rgba(255,255,255,0.08);
  color: #fff;
  transform: translateX(2px);
}

.rvd-nav__item--active {
  background: rgba(255,255,255,0.15);
  color: #fff;
  font-weight: 600;
}

.rvd-nav__item--active::before {
  content: '';
  position: absolute;
  left: 0;
  top: 6px;
  bottom: 6px;
  width: 3px;
  background: #818cf8;
  border-radius: 0 3px 3px 0;
}

.rvd-nav__icon {
  font-size: 16px;
  width: 20px;
  text-align: center;
  flex-shrink: 0;
}

.rvd-nav__label {
  font-size: 13.5px;
  transition: opacity 0.2s, width 0.3s;
}

.rvd-nav__badge {
  margin-left: auto;
  background: #f59e0b;
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 999px;
  transition: opacity 0.2s;
}

.rvd-nav__badge--green { background: #10b981; }

/* ═══════════════════════════════════════════════════
   SIDEBAR PROFILE & DROPDOWN
═══════════════════════════════════════════════════ */
.rvd-sidebar__footer {
  padding: 12px 10px;
  border-top: 1px solid rgba(255,255,255,0.08);
  position: relative;
}

.rvd-profile-card {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.18s;
  user-select: none;
  position: relative;
}

.rvd-profile-card:hover,
.rvd-profile-card--open {
  background: rgba(255,255,255,0.10);
}

.rvd-profile-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: linear-gradient(135deg, #818cf8, #6366f1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
  letter-spacing: 0.5px;
  border: 2px solid rgba(255,255,255,0.2);
}

.rvd-profile-details {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 1px;
  overflow: hidden;
  transition: opacity 0.2s, width 0.3s;
}

.rvd-profile-name {
  font-size: 12.5px;
  font-weight: 600;
  color: #fff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rvd-profile-role {
  font-size: 11px;
  color: rgba(255,255,255,0.45);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rvd-profile-caret {
  font-size: 10px;
  color: rgba(255,255,255,0.4);
  flex-shrink: 0;
  transition: transform 0.2s;
}

/* Dropdown */
.rvd-profile-dropdown {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 10px;
  right: 10px;
  background: #fff;
  border-radius: 12px;
  box-shadow: 0 -4px 24px rgba(0,0,0,0.18), 0 8px 24px rgba(0,0,0,0.12);
  overflow: hidden;
  z-index: 200;
  animation: rvdDropUp 0.18s cubic-bezier(.4,0,.2,1);
}

@keyframes rvdDropUp {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

.rvd-dropdown-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 14px 12px;
  background: #fafafa;
}

.rvd-dropdown-avatar {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: linear-gradient(135deg, #818cf8, #6366f1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}

.rvd-dropdown-name {
  font-size: 13px;
  font-weight: 700;
  color: #111827;
}

.rvd-dropdown-email {
  font-size: 11.5px;
  color: #9ca3af;
  margin-top: 1px;
}

.rvd-dropdown-divider { height: 1px; background: #f3f4f6; }

.rvd-dropdown-item {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 14px;
  background: none;
  border: none;
  font-size: 13px;
  color: #374151;
  cursor: pointer;
  text-align: left;
  transition: background 0.12s, color 0.12s;
  font-weight: 500;
}

.rvd-dropdown-item i {
  font-size: 14px;
  color: #9ca3af;
  width: 18px;
  text-align: center;
}

.rvd-dropdown-item:hover { background: #f9fafb; color: #111827; }

.rvd-dropdown-item--danger { color: #ef4444; }
.rvd-dropdown-item--danger i { color: #ef4444; }
.rvd-dropdown-item--danger:hover { background: #fef2f2; color: #dc2626; }

/* ═══════════════════════════════════════════════════
   REVIEWER PILL (collapsed footer)
═══════════════════════════════════════════════════ */
.rvd-reviewer-pill {
  display: flex;
  align-items: center;
  gap: 10px;
}

.rvd-reviewer-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: rgba(255,255,255,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 14px;
  flex-shrink: 0;
}

.rvd-reviewer-info {
  display: flex;
  flex-direction: column;
  transition: opacity 0.2s, width 0.3s;
  overflow: hidden;
}

.rvd-reviewer-name {
  font-size: 12.5px;
  font-weight: 600;
  color: #fff;
  white-space: nowrap;
}

.rvd-reviewer-role {
  font-size: 11px;
  color: rgba(255,255,255,0.5);
  white-space: nowrap;
}

/* ═══════════════════════════════════════════════════
   MAIN AREA
═══════════════════════════════════════════════════ */
.rvd-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transition: all 0.3s;
}

/* Topbar */
.rvd-topbar {
  height: 60px;
  background: #fff;
  border-bottom: 1px solid #e5e7eb;
  display: flex;
  align-items: center;
  padding: 0 24px;
  gap: 16px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.04);
  flex-shrink: 0;
}

.rvd-topbar__toggle {
  background: none;
  border: none;
  font-size: 18px;
  color: #6b7280;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 6px;
  transition: background 0.15s, color 0.15s;
}

.rvd-topbar__toggle:hover { background: #f3f4f6; color: #111827; }

.rvd-topbar__breadcrumb {
  font-size: 15px;
  font-weight: 600;
  color: #111827;
  flex: 1;
}

.rvd-topbar__right {
  display: flex;
  align-items: center;
  gap: 16px;
}

.rvd-topbar__date {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12.5px;
  color: #9ca3af;
}

/* Content area */
.rvd-content {
  flex: 1;
  overflow-y: auto;
  padding: 28px 28px 40px;
}

/* ═══════════════════════════════════════════════════
   HOME — REDESIGNED HERO BANNER
═══════════════════════════════════════════════════ */
.rvd-hero {
  background: linear-gradient(135deg, #1e1756 0%, #3d3180 45%, #6b5fd4 100%);
  border-radius: 22px;
  padding: 38px 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 28px;
  margin-bottom: 22px;
  position: relative;
  overflow: hidden;
  box-shadow: 0 12px 40px rgba(61,49,128,0.35);
}

.rvd-hero::before {
  content: '';
  position: absolute;
  top: -80px; right: -60px;
  width: 320px; height: 320px;
  border-radius: 50%;
  background: rgba(255,255,255,0.05);
  pointer-events: none;
}

.rvd-hero::after {
  content: '';
  position: absolute;
  bottom: -100px; right: 240px;
  width: 220px; height: 220px;
  border-radius: 50%;
  background: rgba(255,255,255,0.03);
  pointer-events: none;
}

.rvd-hero__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 700;
  color: rgba(255,255,255,0.65);
  text-transform: uppercase;
  letter-spacing: .9px;
  margin-bottom: 10px;
}

.rvd-hero__pulse {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: #34d399;
  box-shadow: 0 0 0 3px rgba(52,211,153,0.3);
  animation: rvdPulse 2s ease-in-out infinite;
}

@keyframes rvdPulse {
  0%,100% { box-shadow: 0 0 0 3px rgba(52,211,153,0.25); }
  50%     { box-shadow: 0 0 0 7px rgba(52,211,153,0.08); }
}

.rvd-hero__title {
  font-size: 30px;
  font-weight: 900;
  color: #fff;
  margin: 0 0 10px;
  letter-spacing: -.5px;
  line-height: 1.2;
}

.rvd-hero__name            { color: #c4b5fd; }
.rvd-hero__sub             { font-size: 14px; color: rgba(255,255,255,0.72); margin: 0 0 20px; line-height: 1.6; }
.rvd-hero__highlight       { color: #fff; font-weight: 800; }
.rvd-hero__highlight--green{ color: #34d399; }

.rvd-hero__cta-row {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.rvd-hero__cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(255,255,255,0.18);
  border: 1px solid rgba(255,255,255,0.25);
  color: #fff;
  font-size: 13px;
  font-weight: 700;
  padding: 10px 20px;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.18s, gap 0.18s;
  backdrop-filter: blur(6px);
}

.rvd-hero__cta:hover { background: rgba(255,255,255,0.28); gap: 12px; }

.rvd-hero__meta {
  font-size: 12px;
  color: rgba(255,255,255,0.55);
  display: flex;
  align-items: center;
  gap: 6px;
}

.rvd-hero__right {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  flex-shrink: 0;
}

.rvd-hero__stat-pill {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: rgba(255,255,255,0.12);
  border: 1px solid rgba(255,255,255,0.18);
  border-radius: 14px;
  padding: 16px 28px;
  gap: 5px;
  backdrop-filter: blur(8px);
  min-width: 90px;
  transition: background 0.18s;
}

.rvd-hero__stat-pill:hover  { background: rgba(255,255,255,0.2); }
.rvd-hsp--green { border-color: rgba(52,211,153,0.3); }
.rvd-hsp--red   { border-color: rgba(252,165,165,0.3); }

.rvd-hsp-val { font-size: 30px; font-weight: 900; color: #fff; line-height: 1; }
.rvd-hsp--green .rvd-hsp-val { color: #34d399; }
.rvd-hsp--red   .rvd-hsp-val { color: #fca5a5; }

.rvd-hsp-lbl {
  font-size: 10px;
  font-weight: 600;
  color: rgba(255,255,255,0.55);
  text-transform: uppercase;
  letter-spacing: .5px;
}

/* ═══════════════════════════════════════════════════
   KPI ROW (replaces old stat cards on home)
═══════════════════════════════════════════════════ */
.rvd-kpi-row {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 14px;
  margin-bottom: 20px;
}

.rvd-kpi {
  border-radius: 16px;
  padding: 18px 18px 0;
  border: 1px solid transparent;
  overflow: hidden;
  min-height: 118px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: transform 0.18s, box-shadow 0.18s;
  cursor: default;
}

.rvd-kpi:hover { transform: translateY(-3px); box-shadow: 0 10px 30px rgba(0,0,0,0.1); }

.rvd-kpi--purple { background: linear-gradient(135deg,#f5f3ff,#ede9fe); border-color: #ddd6fe; }
.rvd-kpi--amber  { background: linear-gradient(135deg,#fffbeb,#fef3c7); border-color: #fde68a; }
.rvd-kpi--green  { background: linear-gradient(135deg,#f0fdf4,#dcfce7); border-color: #bbf7d0; }
.rvd-kpi--red    { background: linear-gradient(135deg,#fff5f5,#fee2e2); border-color: #fecaca; }
.rvd-kpi--blue   { background: linear-gradient(135deg,#f0f9ff,#e0f2fe); border-color: #bae6fd; }

.rvd-kpi__icon {
  width: 36px; height: 36px;
  border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  font-size: 15px;
}

.rvd-kpi--purple .rvd-kpi__icon { background: rgba(124,58,237,.12); color: #7c3aed; }
.rvd-kpi--amber  .rvd-kpi__icon { background: rgba(217,119,6,.12);  color: #d97706; }
.rvd-kpi--green  .rvd-kpi__icon { background: rgba(5,150,105,.12);  color: #059669; }
.rvd-kpi--red    .rvd-kpi__icon { background: rgba(220,38,38,.12);  color: #dc2626; }
.rvd-kpi--blue   .rvd-kpi__icon { background: rgba(2,132,199,.12);  color: #0284c7; }

.rvd-kpi__body { flex: 1; }
.rvd-kpi__val  { display: block; font-size: 30px; font-weight: 900; line-height: 1; letter-spacing: -1px; }
.rvd-kpi--purple .rvd-kpi__val { color: #7c3aed; }
.rvd-kpi--amber  .rvd-kpi__val { color: #d97706; }
.rvd-kpi--green  .rvd-kpi__val { color: #059669; }
.rvd-kpi--red    .rvd-kpi__val { color: #dc2626; }
.rvd-kpi--blue   .rvd-kpi__val { color: #0284c7; }

.rvd-kpi__lbl  { display: block; font-size: 11px; font-weight: 600; color: #6b7280; margin-top: 3px; }

.rvd-kpi__bar  { height: 5px; background: rgba(0,0,0,.07); margin: 0 -18px; }
.rvd-kpi__fill { height: 100%; border-radius: 0 3px 3px 0; transition: width 1.4s cubic-bezier(.4,0,.2,1); }

/* ═══════════════════════════════════════════════════
   CHART CARD SHELL
═══════════════════════════════════════════════════ */
.rvd-chart-card {
  background: #fff;
  border-radius: 18px;
  border: 1px solid #e8edf5;
  overflow: hidden;
  box-shadow: 0 2px 12px rgba(0,0,0,0.05);
}

.rvd-chart-grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  margin-bottom: 18px;
}

.rvd-chart-grid-3 {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 18px;
  margin-bottom: 18px;
}

.rvd-chart-card--span2 { grid-column: span 2; }

/* Chart card header */
.rvd-chart-card__hdr {
  padding: 16px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  color: #fff;
}

.rvd-cc-hdr--purple { background: linear-gradient(135deg,#3d3180,#7c3aed); }
.rvd-cc-hdr--teal   { background: linear-gradient(135deg,#0d7a6e,#10b981); }
.rvd-cc-hdr--indigo { background: linear-gradient(135deg,#2e2e8e,#6366f1); }
.rvd-cc-hdr--rose   { background: linear-gradient(135deg,#881337,#f43f5e); }
.rvd-cc-hdr--amber  { background: linear-gradient(135deg,#92400e,#f59e0b); }
.rvd-cc-hdr--slate  { background: linear-gradient(135deg,#1e293b,#475569); }

.rvd-cc-hdr-left { display: flex; align-items: center; gap: 12px; }
.rvd-cc-hdr-left > i { font-size: 17px; opacity: .9; }
.rvd-cc-title { font-size: 14px; font-weight: 800; color: #fff; }
.rvd-cc-sub   { font-size: 11px; color: rgba(255,255,255,.68); margin-top: 2px; }

.rvd-cc-badge {
  background: rgba(255,255,255,.18);
  border: 1px solid rgba(255,255,255,.22);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: 99px;
  white-space: nowrap;
}

.rvd-cc-badge--warn {
  background: rgba(239,68,68,.35);
  border-color: rgba(239,68,68,.4);
}

.rvd-chart-card__body  { padding: 20px; }
.rvd-cc-body--flush    { padding: 0; }
.rvd-cc-body--center   { display: flex; flex-direction: column; align-items: center; padding: 20px; gap: 10px; }

/* ── Donut layout ── */
.rvd-donut-layout { display: flex; align-items: center; gap: 24px; }

.rvd-donut-wrap {
  position: relative;
  flex-shrink: 0;
  width: 200px; height: 200px;
}

.rvd-donut-wrap canvas {
  display: block !important;
  width: 200px !important;
  height: 200px !important;
}

.rvd-donut-center {
  position: absolute; inset: 0;
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  pointer-events: none;
}

.rvd-dc-num { font-size: 32px; font-weight: 900; color: #0f172a; line-height: 1; }
.rvd-dc-lbl { font-size: 11px; font-weight: 600; color: #94a3b8; margin-top: 2px; }

.rvd-donut-legend { flex: 1; display: flex; flex-direction: column; gap: 8px; }

.rvd-dl-row {
  display: flex; align-items: center; gap: 9px;
  padding: 9px 12px;
  background: #f8fafc;
  border-radius: 10px;
  border: 1px solid #f1f5f9;
  transition: background 0.14s;
}

.rvd-dl-row:hover { background: #f1f5f9; }
.rvd-dl-dot  { width: 10px; height: 10px; border-radius: 3px; flex-shrink: 0; }
.rvd-dl-lbl  { flex: 1; font-size: 12px; font-weight: 600; color: #374151; }
.rvd-dl-val  { font-size: 14px; font-weight: 900; }

/* ── Gauge ── */
.rvd-gauge-info   { text-align: center; }
.rvd-gauge-val    { display: block; font-size: 30px; font-weight: 900; color: #dc2626; }
.rvd-gauge-lbl    { display: block; font-size: 11px; font-weight: 600; color: #94a3b8; margin-top: 3px; }

.rvd-gauge-chip {
  display: inline-flex; align-items: center; gap: 5px;
  font-size: 11px; font-weight: 700;
  padding: 4px 12px; border-radius: 99px;
}

.rvd-gauge-chip--green { background: #dcfce7; color: #15803d; border: 1px solid #bbf7d0; }

/* ── Priority Queue ── */
.rvd-queue-item {
  display: flex;
  align-items: center;
  padding: 13px 18px;
  border-bottom: 1px solid #f1f5f9;
  cursor: pointer;
  transition: background 0.14s;
}

.rvd-queue-item:last-child { border-bottom: none; }
.rvd-queue-item:hover { background: #f8fafc; }

.rvd-qi-bar {
  width: 4px; height: 40px;
  border-radius: 99px;
  flex-shrink: 0;
  margin-right: 14px;
}

.rvd-qi-bar--amber { background: #d97706; }
.rvd-qi-bar--green { background: #059669; }
.rvd-qi-bar--red   { background: #dc2626; }

.rvd-qi-body { flex: 1; min-width: 0; }
.rvd-qi-top  { display: flex; align-items: center; gap: 8px; margin-bottom: 3px; }
.rvd-qi-num  { font-size: 12px; font-weight: 800; color: #1e293b; }

.rvd-chip--sm { font-size: 9px !important; padding: 2px 8px !important; }

.rvd-qi-prog {
  font-size: 12px;
  font-weight: 500;
  color: #64748b;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rvd-qi-arrow { color: #cbd5e1; font-size: 11px; margin-left: 10px; }
.rvd-queue-item:hover .rvd-qi-arrow { color: #5443AD; }

.rvd-queue-empty {
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  padding: 36px 20px; color: #94a3b8; gap: 8px;
}

.rvd-queue-empty i { font-size: 26px; }
.rvd-queue-empty p { font-size: 13px; font-weight: 600; margin: 0; }

/* ═══════════════════════════════════════════════════
   OLD WELCOME BANNER (kept for fallback)
═══════════════════════════════════════════════════ */
.rvd-welcome-banner {
  background: linear-gradient(135deg, #3730a3 0%, #6d28d9 100%);
  border-radius: 16px;
  padding: 28px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
  overflow: hidden;
  position: relative;
}

.rvd-welcome-banner::before {
  content: '';
  position: absolute;
  top: -40px; right: 80px;
  width: 160px; height: 160px;
  background: rgba(255,255,255,0.05);
  border-radius: 50%;
}

.rvd-welcome-banner::after {
  content: '';
  position: absolute;
  bottom: -30px; right: 40px;
  width: 100px; height: 100px;
  background: rgba(255,255,255,0.04);
  border-radius: 50%;
}

.rvd-welcome-title {
  font-size: 20px;
  font-weight: 700;
  color: #fff;
  margin: 0 0 8px;
}

.rvd-welcome-sub {
  font-size: 13.5px;
  color: rgba(255,255,255,0.7);
  max-width: 480px;
  margin: 0;
  line-height: 1.6;
}

.rvd-welcome-illustration {
  font-size: 56px;
  color: rgba(255,255,255,0.12);
  flex-shrink: 0;
  z-index: 1;
}

/* ═══════════════════════════════════════════════════
   OLD STAT CARDS (proposals / completed sections)
═══════════════════════════════════════════════════ */
.rvd-stats-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 24px;
}

.rvd-stat-card {
  border-radius: 14px;
  padding: 20px;
  display: flex;
  align-items: center;
  gap: 16px;
  position: relative;
  overflow: hidden;
  transition: transform 0.2s, box-shadow 0.2s;
  cursor: default;
}

.rvd-stat-card:hover { transform: translateY(-3px); box-shadow: 0 8px 28px rgba(0,0,0,0.12); }

.rvd-stat-card--blue  { background: linear-gradient(135deg,#eff6ff,#dbeafe); }
.rvd-stat-card--amber { background: linear-gradient(135deg,#fffbeb,#fef3c7); }
.rvd-stat-card--green { background: linear-gradient(135deg,#ecfdf5,#d1fae5); }
.rvd-stat-card--red   { background: linear-gradient(135deg,#fef2f2,#fee2e2); }

.rvd-stat-card__icon {
  font-size: 22px;
  width: 48px; height: 48px;
  border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}

.rvd-stat-card--blue  .rvd-stat-card__icon { background: #dbeafe; color: #1d4ed8; }
.rvd-stat-card--amber .rvd-stat-card__icon { background: #fde68a; color: #b45309; }
.rvd-stat-card--green .rvd-stat-card__icon { background: #a7f3d0; color: #047857; }
.rvd-stat-card--red   .rvd-stat-card__icon { background: #fecaca; color: #b91c1c; }

.rvd-stat-card__body { display: flex; flex-direction: column; }

.rvd-stat-card__num {
  font-size: 30px;
  font-weight: 800;
  line-height: 1;
  margin-bottom: 4px;
}

.rvd-stat-card--blue  .rvd-stat-card__num { color: #1e40af; }
.rvd-stat-card--amber .rvd-stat-card__num { color: #92400e; }
.rvd-stat-card--green .rvd-stat-card__num { color: #065f46; }
.rvd-stat-card--red   .rvd-stat-card__num { color: #991b1b; }

.rvd-stat-card__label {
  font-size: 12px;
  font-weight: 500;
  color: #6b7280;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.rvd-stat-card__glow {
  position: absolute;
  right: -10px; top: -10px;
  width: 60px; height: 60px;
  border-radius: 50%;
  opacity: 0.15;
}

.rvd-stat-card--blue  .rvd-stat-card__glow { background: #3b82f6; }
.rvd-stat-card--amber .rvd-stat-card__glow { background: #f59e0b; }
.rvd-stat-card--green .rvd-stat-card__glow { background: #10b981; }
.rvd-stat-card--red   .rvd-stat-card__glow { background: #ef4444; }

/* ═══════════════════════════════════════════════════
   OLD HOME PANELS (kept for non-home sections)
═══════════════════════════════════════════════════ */
.rvd-home-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.rvd-panel {
  background: #fff;
  border-radius: 14px;
  box-shadow: 0 1px 6px rgba(0,0,0,0.06);
  overflow: hidden;
}

.rvd-panel__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  border-bottom: 1px solid #f3f4f6;
}

.rvd-panel__title {
  font-size: 14px;
  font-weight: 700;
  color: #111827;
  margin: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}

.rvd-panel__title i { color: #6366f1; }

.rvd-panel__link {
  background: none;
  border: none;
  font-size: 12.5px;
  color: #6366f1;
  cursor: pointer;
  font-weight: 500;
  transition: color 0.15s;
}

.rvd-panel__link:hover { color: #4f46e5; }
.rvd-panel__body { padding: 12px 20px 20px; }

/* Activity list */
.rvd-activity-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px solid #f9fafb;
  cursor: pointer;
  transition: background 0.12s;
  border-radius: 6px;
}

.rvd-activity-item:hover { background: #fafafa; }
.rvd-activity-item:last-child { border-bottom: none; }

.rvd-activity-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}

.rvd-dot--amber { background: #f59e0b; }
.rvd-dot--green { background: #10b981; }
.rvd-dot--red   { background: #ef4444; }

.rvd-activity-body { flex: 1; display: flex; flex-direction: column; gap: 2px; }
.rvd-activity-num  { font-size: 13px; font-weight: 700; color: #111827; }
.rvd-activity-prog { font-size: 11.5px; color: #9ca3af; }

.rvd-activity-status {
  font-size: 10.5px;
  padding: 3px 8px;
  border-radius: 999px;
  font-weight: 600;
  white-space: nowrap;
}

/* Progress bars */
.rvd-progress-item { margin-bottom: 16px; }

.rvd-progress-meta {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: #6b7280;
  margin-bottom: 5px;
  font-weight: 500;
}

.rvd-progress-track {
  height: 8px;
  background: #f3f4f6;
  border-radius: 999px;
  overflow: hidden;
}

.rvd-progress-fill {
  height: 100%;
  border-radius: 999px;
  transition: width 0.8s cubic-bezier(.4,0,.2,1);
}

.rvd-progress-fill--amber { background: linear-gradient(90deg, #f59e0b, #fbbf24); }
.rvd-progress-fill--green { background: linear-gradient(90deg, #10b981, #34d399); }
.rvd-progress-fill--red   { background: linear-gradient(90deg, #ef4444, #f87171); }

/* Donut bar */
.rvd-donut-row {
  display: flex;
  height: 12px;
  border-radius: 999px;
  overflow: hidden;
  margin-top: 20px;
  gap: 2px;
}

.rvd-donut-segment {
  height: 100%;
  border-radius: 999px;
  transition: flex 0.8s cubic-bezier(.4,0,.2,1);
}

.rvd-legend-row { display: flex; gap: 16px; margin-top: 10px; }

.rvd-legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11.5px;
  color: #6b7280;
}

.rvd-legend-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  display: inline-block;
}

/* ═══════════════════════════════════════════════════
   SECTION HEADER
═══════════════════════════════════════════════════ */
.rvd-section-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 20px;
}

.rvd-section-title {
  font-size: 20px;
  font-weight: 800;
  color: #111827;
  margin: 0 0 4px;
}

.rvd-section-sub {
  font-size: 13px;
  color: #9ca3af;
  margin: 0;
  max-width: 520px;
  line-height: 1.5;
}

.rvd-completed-badge {
  background: #d1fae5;
  color: #065f46;
  font-size: 13px;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 999px;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

/* ═══════════════════════════════════════════════════
   FILTER BAR
═══════════════════════════════════════════════════ */
.rvd-filter-bar {
  display: flex;
  gap: 12px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.rvd-filter-search { flex: 1; min-width: 220px; position: relative; }

.rvd-filter-search__icon {
  position: absolute;
  left: 12px; top: 50%;
  transform: translateY(-50%);
  color: #9ca3af;
  font-size: 13px;
}

.rvd-filter-search__input {
  width: 100%;
  height: 40px;
  padding: 0 14px 0 36px;
  border: 1.5px solid #e5e7eb;
  border-radius: 10px;
  font-size: 13.5px;
  color: #111827;
  background: #fff;
  transition: border-color 0.18s, box-shadow 0.18s;
  outline: none;
  box-sizing: border-box;
}

.rvd-filter-search__input:focus {
  border-color: #6366f1;
  box-shadow: 0 0 0 3px rgba(99,102,241,0.12);
}

.rvd-filter-select {
  height: 40px;
  padding: 0 14px;
  border: 1.5px solid #e5e7eb;
  border-radius: 10px;
  font-size: 13.5px;
  color: #374151;
  background: #fff;
  cursor: pointer;
  outline: none;
  transition: border-color 0.18s;
}

.rvd-filter-select:focus { border-color: #6366f1; }

/* Results meta */
.rvd-results-meta {
  display: flex;
  align-items: center;
  font-size: 13px;
  color: #6b7280;
  margin-bottom: 16px;
}

.rvd-results-meta a { color: #6366f1; text-decoration: none; cursor: pointer; }
.rvd-results-meta a:hover { text-decoration: underline; }

/* ═══════════════════════════════════════════════════
   PROPOSAL CARDS
═══════════════════════════════════════════════════ */
.rvd-proposal-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 18px;
}

.rvd-proposal-card {
  background: #fff;
  border-radius: 14px;
  border: 1.5px solid #f3f4f6;
  padding: 18px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 14px;
  transition: transform 0.2s cubic-bezier(.4,0,.2,1), box-shadow 0.2s, border-color 0.2s;
  position: relative;
  overflow: hidden;
}

.rvd-proposal-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: linear-gradient(90deg, #6366f1, #8b5cf6);
  opacity: 0;
  transition: opacity 0.2s;
}

.rvd-proposal-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 32px rgba(99,102,241,0.12);
  border-color: #e0e7ff;
}

.rvd-proposal-card:hover::before { opacity: 1; }

.rvd-proposal-card__num-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
}

.rvd-proposal-num {
  font-size: 12px;
  font-weight: 700;
  color: #6366f1;
  background: #eef2ff;
  padding: 3px 10px;
  border-radius: 6px;
  letter-spacing: 0.3px;
}

.rvd-proposal-program {
  font-size: 14.5px;
  font-weight: 700;
  color: #111827;
  margin: 0 0 4px;
  line-height: 1.4;
}

.rvd-proposal-applicant {
  font-size: 12.5px;
  color: #9ca3af;
  margin: 0;
  display: flex;
  align-items: center;
  gap: 5px;
}

.rvd-proposal-card__mid {
  display: flex;
  flex-direction: column;
  gap: 6px;
  background: #fafafa;
  border-radius: 10px;
  padding: 12px;
}

.rvd-info-pair { display: flex; justify-content: space-between; align-items: center; font-size: 12.5px; }
.rvd-info-pair__label { color: #9ca3af; font-weight: 500; }
.rvd-info-pair__val   { color: #374151; font-weight: 600; }
.rvd-score-val        { color: #6366f1 !important; }

.rvd-mono-chip {
  background: #f3f4f6;
  color: #374151;
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-size: 11px;
  padding: 2px 7px;
  border-radius: 5px;
  font-weight: 600;
}

/* Score bar */
.rvd-proposal-card__score-bar {
  display: flex;
  align-items: center;
  gap: 10px;
}

.rvd-score-track {
  flex: 1;
  height: 6px;
  background: #f3f4f6;
  border-radius: 999px;
  overflow: hidden;
}

.rvd-score-fill {
  height: 100%;
  background: linear-gradient(90deg, #6366f1, #8b5cf6);
  border-radius: 999px;
  transition: width 0.6s cubic-bezier(.4,0,.2,1);
}

.rvd-score-pct { font-size: 11px; color: #6b7280; font-weight: 600; white-space: nowrap; }

.rvd-proposal-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 8px;
  border-top: 1px solid #f3f4f6;
}

.rvd-group-tag {
  font-size: 11.5px;
  color: #9ca3af;
  display: flex;
  align-items: center;
  gap: 5px;
}

.rvd-open-link {
  font-size: 12px;
  font-weight: 600;
  color: #6366f1;
  display: flex;
  align-items: center;
  gap: 5px;
  transition: gap 0.15s;
}

.rvd-proposal-card:hover .rvd-open-link { gap: 8px; }

/* ═══════════════════════════════════════════════════
   CHIPS
═══════════════════════════════════════════════════ */
.rvd-chip {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}

.rvd-chip--amber { background: #fef3c7; color: #b45309; }
.rvd-chip--green { background: #d1fae5; color: #065f46; }
.rvd-chip--red   { background: #fee2e2; color: #991b1b; }
.rvd-chip--blue  { background: #dbeafe; color: #1d4ed8; }
.rvd-chip--sm    { font-size: 9px !important; padding: 2px 8px !important; }

/* ═══════════════════════════════════════════════════
   PAGINATION
═══════════════════════════════════════════════════ */
.rvd-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 32px;
  padding-bottom: 24px;
}

.rvd-page-btn {
  min-width: 36px;
  height: 36px;
  padding: 0 10px;
  border: 1px solid #e5e7eb;
  background: #fff;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 500;
  color: #374151;
  cursor: pointer;
  transition: all 0.15s;
}

.rvd-page-btn:hover:not([disabled]):not(.rvd-page-btn--ellipsis) {
  background: #f3f4f6;
  border-color: #6366f1;
  color: #6366f1;
}

.rvd-page-btn--active   { background: #6366f1 !important; border-color: #6366f1 !important; color: #fff !important; }
.rvd-page-btn--ellipsis { border: none; background: transparent; cursor: default; color: #9ca3af; }
.rvd-page-btn--nav      { font-size: 12px; }
.rvd-page-btn[disabled] { opacity: 0.4; cursor: not-allowed; }

/* ═══════════════════════════════════════════════════
   COMPLETED TABLE
═══════════════════════════════════════════════════ */
.rvd-completed-table-wrap {
  background: #fff;
  border-radius: 14px;
  box-shadow: 0 1px 6px rgba(0,0,0,0.06);
  overflow: hidden;
}

.rvd-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13.5px;
}

.rvd-table thead th {
  padding: 14px 18px;
  text-align: left;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #9ca3af;
  background: #fafafa;
  border-bottom: 1px solid #f3f4f6;
}

.rvd-table-row td {
  padding: 14px 18px;
  border-bottom: 1px solid #f9fafb;
  color: #374151;
  vertical-align: middle;
}

.rvd-table-row:last-child td { border-bottom: none; }
.rvd-table-row { transition: background 0.12s; }
.rvd-table-row:hover { background: #fafafa; }

.rvd-score-pill {
  background: #eef2ff;
  color: #4f46e5;
  padding: 3px 10px;
  border-radius: 6px;
  font-weight: 700;
  font-size: 12.5px;
}

.rvd-muted { color: #d1d5db; }

.rvd-tbl-btn {
  background: none;
  border: 1.5px solid #e5e7eb;
  padding: 5px 12px;
  border-radius: 7px;
  font-size: 12px;
  color: #6366f1;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 5px;
  font-weight: 600;
  transition: background 0.15s, border-color 0.15s;
}

.rvd-tbl-btn:hover { background: #eef2ff; border-color: #c7d2fe; }

/* ═══════════════════════════════════════════════════
   EMPTY STATE
═══════════════════════════════════════════════════ */
.rvd-empty-state {
  text-align: center;
  padding: 60px 20px;
  color: #9ca3af;
}

.rvd-empty-state i {
  font-size: 48px;
  margin-bottom: 16px;
  display: block;
  color: #d1d5db;
}

.rvd-empty-state h3 { font-size: 16px; font-weight: 700; color: #374151; margin: 0 0 8px; }
.rvd-empty-state p  { font-size: 13.5px; max-width: 360px; margin: 0 auto; line-height: 1.6; }
.rvd-empty-state--sm { padding: 24px 16px; }
.rvd-empty-state--sm i { font-size: 28px; margin-bottom: 8px; }

/* ═══════════════════════════════════════════════════
   NO ACCESS
═══════════════════════════════════════════════════ */
.rvd-no-access {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 50vh;
  text-align: center;
  color: #9ca3af;
  padding: 40px;
}

.rvd-no-access i { font-size: 52px; color: #ef4444; margin-bottom: 20px; }
.rvd-no-access h3 { font-size: 18px; font-weight: 700; color: #374151; margin: 0 0 8px; }
.rvd-no-access p { font-size: 13.5px; max-width: 360px; line-height: 1.6; }

/* ═══════════════════════════════════════════════════
   RESPONSIVE
═══════════════════════════════════════════════════ */
@media (max-width: 1200px) {
  .rvd-kpi-row { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 1060px) {
  .rvd-chart-grid-3 { grid-template-columns: 1fr 1fr; }
  .rvd-chart-card--span2 { grid-column: span 2; }
}

@media (max-width: 900px) {
  .rvd-stats-row { grid-template-columns: 1fr 1fr; }
  .rvd-home-grid { grid-template-columns: 1fr; }
  .rvd-sidebar   { width: 64px; min-width: 64px; }
  .rvd-brand-text,
  .rvd-nav__label,
  .rvd-nav__badge,
  .rvd-reviewer-info { display: none; }
  .rvd-kpi-row { grid-template-columns: repeat(2, 1fr); }
  .rvd-chart-grid-2,
  .rvd-chart-grid-3 { grid-template-columns: 1fr; }
  .rvd-chart-card--span2 { grid-column: span 1; }
  .rvd-hero { flex-direction: column; align-items: flex-start; }
  .rvd-hero__right { width: 100%; }
  .rvd-donut-layout { flex-direction: column; align-items: center; }
}

@media (max-width: 600px) {
  .rvd-stats-row    { grid-template-columns: 1fr; }
  .rvd-kpi-row      { grid-template-columns: 1fr 1fr; }
  .rvd-content      { padding: 16px; }
  .rvd-welcome-banner { padding: 20px; }
  .rvd-welcome-illustration { display: none; }
  .rvd-proposal-grid { grid-template-columns: 1fr; }
  .rvd-hero__title  { font-size: 22px; }
  .rvd-hero         { padding: 24px 20px; }
}

sp_widget.script:
(function() {

  // ── Current user ──────────────────────────────────────────
  var userGr = new GlideRecord('sys_user');
  if (userGr.get(gs.getUserID())) {
    data.currentUser = {
      sys_id:     userGr.getUniqueValue(),
      name:       userGr.getDisplayValue('name')  || 'Reviewer',
      first_name: userGr.getValue('first_name')   || '',
      last_name:  userGr.getValue('last_name')    || '',
      email:      userGr.getValue('email')        || '',
      title:      userGr.getValue('title')        || 'Grant Reviewer',
      initials:   (userGr.getValue('first_name') || 'R').charAt(0).toUpperCase() +
                  (userGr.getValue('last_name')  || '').charAt(0).toUpperCase()
    };
  } else {
    data.currentUser = { name:'Guest', first_name:'', last_name:'', email:'', title:'', initials:'G', sys_id:'' };
  }

  data.logoutUrl   = '/login.do?logout=true';
  data.profilePage = '?id=user_profile';
  data.canRead     = true;
  data.reviews     = [];

  // ── Full stats object (all 5 statuses) ───────────────────
  data.stats = {
    total:             0,
    inProgress:        0,
    completed:         0,
    escalated:         0,
    declined:          0,
    pending:           0,
    overdue:           0,
    dueSoon:           0   // deadline within 3 days
  };

  var userId = gs.getUserID();
  var today  = new GlideDateTime();

  // ── Groups ───────────────────────────────────────────────
  var groups = [];
  var grMem  = new GlideRecord('sys_user_grmember');
  grMem.addQuery('user', userId);
  grMem.query();
  while (grMem.next()) { groups.push(grMem.getValue('group')); }

  if (groups.length === 0) return;

  // ── Query reviews ────────────────────────────────────────
  var gr = new GlideRecord('x_enno_gatenow_grant_review');
  var qc = gr.addQuery('assignment_group', 'IN', groups.join(','));
  for (var i = 0; i < groups.length; i++) {
    var orCond = qc.addOrCondition('status', 'Review completed');
    orCond.addCondition('reviewer', 'CONTAINS', groups[i]);
  }
  gr.orderBy('number');
  gr.query();

  while (gr.next()) {
    var status = gr.getDisplayValue('status');

    // deadline handling
    var deadlineVal  = gr.getValue('review_deadline') || '';
    var deadlineDisp = deadlineVal ? gr.getDisplayValue('review_deadline') : '';
    var isOverdue    = false;
    var isDueSoon    = false;

    if (deadlineVal) {
      var dl = new GlideDateTime(deadlineVal);
      var diffMs = dl.getNumericValue() - today.getNumericValue();
      var diffDays = diffMs / (1000 * 60 * 60 * 24);
      if (diffDays < 0 && status !== 'Review completed' && status !== 'Declined by Reviewer') {
        isOverdue = true;
      } else if (diffDays >= 0 && diffDays <= 3 && status !== 'Review completed' && status !== 'Declined by Reviewer') {
        isDueSoon = true;
      }
    }

    // reviewer groups (list field — comma separated sys_ids)
    var reviewerDisplay = gr.getDisplayValue('reviewer') || '';

    // program lookup
    var programName = '', programCategory = '', programNumber = '';
    var programSysId = gr.getValue('program');
    if (programSysId) {
      var progGr = new GlideRecord('x_enno_gatenow_grant_program');
      if (progGr.get(programSysId)) {
        programName     = progGr.getDisplayValue('program_name') || '';
        programCategory = progGr.getDisplayValue('category')     || '';
        programNumber   = progGr.getValue('number')              || '';
      }
    }

    // applicant lookup
    var applicantName = '', applicantNumber = '';
    var applicantSysId = gr.getValue('applicant');
    if (applicantSysId) {
      var appGr = new GlideRecord('x_enno_gatenow_service_applicants');
      if (appGr.get(applicantSysId)) {
        applicantName   = ((appGr.getValue('first_name') || '') + ' ' + (appGr.getValue('last_name') || '')).trim();
        applicantNumber = appGr.getValue('number') || '';
      }
    }

    // stats counters
    data.stats.total++;
    if (status === 'Review in progress')    data.stats.inProgress++;
    else if (status === 'Review completed') data.stats.completed++;
    else if (status === 'Escalated')        data.stats.escalated++;
    else if (status === 'Declined by Reviewer') data.stats.declined++;
    else if (status === 'Review pending')   data.stats.pending++;

    if (isOverdue) data.stats.overdue++;
    if (isDueSoon) data.stats.dueSoon++;

    data.reviews.push({
      sys_id:           gr.getUniqueValue(),
      number:           gr.getValue('number')                  || '',
      status:           status,
      assignment_group: gr.getDisplayValue('assignment_group') || '',
      reviewer:         reviewerDisplay,
      score:            gr.getValue('score')                   || '',
      applicant:        applicantName,
      applicant_number: applicantNumber,
      program:          programName,
      program_number:   programNumber,
      program_category: programCategory,
      decision_type:    gr.getDisplayValue('decision_type')    || '',
      review_deadline:  deadlineDisp,
      deadline_raw:     deadlineVal,
      is_overdue:       isOverdue,
      is_due_soon:      isDueSoon
    });
  }

  // ── Save review ───────────────────────────────────────────
  if (input && input.action === 'save_review' && input.review_sys_id) {
    var reviewId = String(input.review_sys_id);
    var form     = input.form || {};
    var grUpdate = new GlideRecord('x_enno_gatenow_grant_review');
    if (grUpdate.get(reviewId)) {
      if (groups.indexOf(grUpdate.getValue('assignment_group')) === -1) {
        data.success = false; data.error = 'Not allowed.'; return;
      }
      if (form.decision_type)         grUpdate.setValue('decision_type',  form.decision_type);
      if (form.status)                grUpdate.setValue('status',         form.status);
      if (!gs.nil(form.score))        grUpdate.setValue('score',          form.score);
      if (!gs.nil(form.review_notes)) grUpdate.setValue('work_notes',     form.review_notes);
      grUpdate.update();
      data.success = true;
    } else {
      data.success = false; data.error = 'Not found.';
    }
  }

})();
